        if a.starts_with(b"HTTP/") {
            out.push(text::named("Http-Version", a));
            out.push(text::named("Status-Code", b));
            out.push(text::named("Reason-Phrase", c));
        } else {
            out.push(text::named("Method", a));
            out.push(text::named("Path", b));
            out.push(text::named("Http-Version", c));
        }
